import unittest

class MyTestCase(unittest.TestCase):
    def setUp(self):
        print("setUp")
    @unittest.skip("skip")
    def test_skip(self):
        print("test_skip")
    def test_fail_setup(self):
        print("test_fail_setup")
    def tearDown(self):
        print("tearDown")

class FailSetup(unittest.TestCase):
    def setUp(self):
        print("setUp")
        raise Exception("setUp failed")
    def test_one(self):
        print("test_one")
    def tearDown(self):
        print("tearDown")

print("Running test_skip:")
suite = unittest.TestSuite()
suite.addTest(MyTestCase("test_skip"))
unittest.TextTestRunner().run(suite)

print("\nRunning FailSetup:")
suite = unittest.TestSuite()
suite.addTest(FailSetup("test_one"))
unittest.TextTestRunner().run(suite)
EOF
python3 check_unittest.py

